-- Independent potential-capability, live-relationship and closed-raw boundaries.
begin;
\ir phase5a/fixture.sql
do $$declare tab record;fn record;client text;r text;actual text[];expected text[];
 keys text[]:=array['games.correct','games.create','games.finalize','games.manage','games.operate','games.publish','games.view'];
begin
 perform pg_temp.check('only seven finite game permissions','CATALOG',(select array_agg(key order by key)=keys from public.permissions where key like 'games.%'));
 perform pg_temp.check('Sports reused without new module or broad role','CATALOG',(select count(*)=14 from public.modules where key <> 'payments') and (select count(*)=21 from public.roles WHERE key not in('competition_manager','merchant_owner','merchant_admin','location_manager','offer_editor','redemption_clerk','sales_rep','regional_manager','support_reviewer')));
 for r in select key from public.roles order by key loop
  expected:=case
   when r in('super_administrator','platform_administrator','organization_owner','organization_administrator') then keys
   when r='athletic_director' then array['games.correct','games.create','games.finalize','games.manage','games.operate','games.view']
   when r in('program_administrator','sport_administrator') then array['games.create','games.finalize','games.manage','games.operate','games.view']
   when r in('team_administrator','head_coach') then array['games.manage','games.view']
   when r='scorekeeper' then array['games.operate','games.view']
   when r in('assistant_coach','team_staff','livestream_operator') then array['games.view']
   else array[]::text[] end;
  select coalesce(array_agg(p.key order by p.key),array[]::text[]) into actual from public.roles role join public.role_permissions rp on rp.role_id=role.id join public.permissions p on p.id=rp.permission_id where role.key=r and p.key like 'games.%';
  perform pg_temp.check('minimum role permission mapping '||r,'CATALOG',actual=expected);
 end loop;
 for tab in select c.oid,n.nspname schema_name,c.relname,c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname in('public','boss_private') and (c.relname='games' or c.relname='sports' or c.relname like 'game_%') loop
  perform pg_temp.check(tab.schema_name||'.'||tab.relname||' RLS enabled','RLS',tab.relrowsecurity);
  foreach client in array array['anon','authenticated','service_role'] loop
   perform pg_temp.check(tab.schema_name||'.'||tab.relname||' raw closed '||client,'RLS',not has_table_privilege(client,tab.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'));
  end loop;
 end loop;
 for fn in select p.oid,n.nspname schema_name,p.proname,p.prosecdef,p.proconfig,p.proacl,p.proowner,p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='boss_private' and p.proname like 'game%') or (n.nspname='public' and p.proname in('boss_games_read','boss_games_mutate')) loop
  perform pg_temp.check(fn.signature||' has fixed empty search path','RPC',coalesce('search_path=""'=any(fn.proconfig),false));
  perform pg_temp.check(fn.signature||' PUBLIC execute closed','RPC',not exists(select 1 from aclexplode(coalesce(fn.proacl,acldefault('f',fn.proowner)))a where a.grantee=0 and a.privilege_type='EXECUTE'));
  perform pg_temp.check(fn.signature||' anonymous and service execute closed','RPC',not has_function_privilege('anon',fn.oid,'EXECUTE') and not has_function_privilege('service_role',fn.oid,'EXECUTE'));
  if fn.schema_name='public' then perform pg_temp.check(fn.signature||' invoker entry authenticated only','RPC',not fn.prosecdef and has_function_privilege('authenticated',fn.oid,'EXECUTE'));
  elsif fn.proname not in('games_read','games_mutate','game_read','game_mutate') then perform pg_temp.check(fn.signature||' private helper closed','RPC',not has_function_privilege('authenticated',fn.oid,'EXECUTE'));end if;
 end loop;
end$$;
set local role authenticated;
select pg_temp.actor('admin');
select pg_temp.create_game('internal','internal');
select pg_temp.create_game('external','external');
select pg_temp.create_game('wildcats','wildcats','wildcats');
select pg_temp.create_game('sibling','sibling','tigers');
select pg_temp.game_op('game.roster.snapshot','internal');
select pg_temp.game_op('game.operator.assign','internal',jsonb_build_object('person_id',pg_temp.f('scorer'),'role_assignment_id',pg_temp.f('role-scorer'),'function_key','scorekeeper','team_id',pg_temp.f('falcons'),'ends_at',now()+interval '1 hour'));
select pg_temp.denied('cannot link forged event UUID',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('forged-event'),pg_temp.create_command('external')||jsonb_build_object('input',(pg_temp.create_command('external')->'input')||jsonb_build_object('event_id',pg_temp.f('missing-event')))));
select pg_temp.denied('cannot link cross-tenant event',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('cross-event'),pg_temp.create_command('other','other-team')));
select pg_temp.state_denied('cannot forge primary team outside Calendar target',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('forged-team'),pg_temp.create_command('denial','tigers')));
