select pg_temp.denied('cannot assign operator using different actor role',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('wrong-person-role'),pg_temp.game_command('game.operator.assign','internal',jsonb_build_object('person_id',pg_temp.f('scorer'),'role_assignment_id',pg_temp.f('role-coach'),'function_key','scorekeeper','team_id',pg_temp.f('falcons'),'ends_at',now()+interval '1 hour'))));
select pg_temp.denied('livestream role grants no score operator function',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('streamer-assign'),pg_temp.game_command('game.operator.assign','internal',jsonb_build_object('person_id',pg_temp.f('streamer'),'role_assignment_id',pg_temp.f('role-streamer'),'function_key','scorekeeper','team_id',pg_temp.f('falcons'),'ends_at',now()+interval '1 hour'))));
select pg_temp.denied('missing operator assignment cannot be ended',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('missing-operator-end'),pg_temp.game_command('game.operator.end','internal',jsonb_build_object('assignment_id',pg_temp.f('missing-operator')))));
reset role;
