select pg_temp.check('Falcons coach can manage its external game under enabled feature policy','TEAM_SCOPE',(select (g->'capabilities'->>'manage')::boolean and (g->'capabilities'->>'roster_snapshot')::boolean and not(g->'capabilities'->>'operate')::boolean from jsonb_array_elements(public.boss_games_read(pg_temp.query('external'))->'games')g));
select pg_temp.check('one-side coach can view matchup but cannot manage other Boss competitor','TEAM_SCOPE',(select not(g->'capabilities'->>'manage')::boolean and not(g->'capabilities'->>'roster_snapshot')::boolean and jsonb_array_length(g->'roster')=1 and g->'roster'->0->>'team_id'=pg_temp.f('falcons')::text from jsonb_array_elements(public.boss_games_read(pg_temp.query('internal'))->'games')g));
select pg_temp.denied('one-side coach cannot snapshot both internal competitor rosters',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('coach-internal-rosters'),pg_temp.game_command('game.roster.snapshot','internal')));
select pg_temp.denied('head coach is not automatically live operator',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('coach-operate'),pg_temp.game_command('game.score.set','internal','{"primary_score":10,"opponent_score":2}')));
select pg_temp.actor('streamer');
select pg_temp.check('livestream role reads safe matchup without operating or roster privileges','PROJECTION',(select not(g->'capabilities'->>'operate')::boolean and not(g->'capabilities'->>'manage')::boolean and jsonb_array_length(g->'roster')=0 and jsonb_array_length(g->'operators')=0 from jsonb_array_elements(public.boss_games_read(pg_temp.query('internal'))->'games')g));
select pg_temp.denied('livestream role cannot mutate score even by known game UUID',format('select public.boss_games_mutate(%L,%L)',pg_temp.f('streamer-known-score'),pg_temp.game_command('game.score.set','internal','{"primary_score":1,"opponent_score":0}')));
select pg_temp.actor('program');
select pg_temp.check('exact program role manages both participating teams in its own unit','TEAM_SCOPE',(select (g->'capabilities'->>'manage')::boolean from jsonb_array_elements(public.boss_games_read(pg_temp.query('internal'))->'games')g));
select pg_temp.denied('exact program does not inherit sibling unit',format('select public.boss_games_read(%L)',pg_temp.query('sibling')));
